async function join(code){const r=await window.onlineGame.joinRoom(code,gameId,{nickname,avatar});if(!r.ok){say(r.message||"Не удалось войти.");return}settings=r.settings||{};document.getElementById("setup").classList.add("hidden");if(gameId==="codenames"){const area=document.getElementById("roomArea");if(state)render();else if(area)area.innerHTML='<section class="panel center"><h2>Открываем игровой стол…</h2></section>';return;}renderRoomLobby()}
