function header(t){if(gameId==="alias")return '<section class="game-title-panel"><div class="game-title-emblem">KZ</div><div class="game-title-copy"><div class="game-title-kicker">АРХИВ KAZO / ВЕРБАЛЬНАЯ РАЗВЕДКА</div><h2>'+esc(t)+'</h2><p>Оперативный канал · командная связь активна</p></div><div id="notice" class="status hidden"></div></section>';const icons={alias:"💬",codenames:"🗝️",spy:"🕶️",imaginarium:"🎨",mafia:"🌒",battleship:"🚢",quiz:"🧠",truth:"⚖️",charades:"🎭",associations:"💭","dots-duel":"🔲",territory:"🟩",codebreaker:"🔐","memory-duel":"🧩","number-duel":"🎯","word-duel":"🔤"};const subtitles={alias:"Объясняй быстрее, думай точнее",codenames:"Слова — твои улики. Подсказка — твой ключ.",spy:"Сохрани легенду. Найди того, кто не в теме.",imaginarium:"У каждой карты своя история.",mafia:"Город засыпает. Начинается игра.",battleship:"Планируй каждый выстрел.",quiz:"Знания решают всё.",truth:"Доверяй фактам, но проверяй интуицию.",charades:"Покажи идею без единого слова.",associations:"Связывай неожиданные смыслы."};return '<section class="game-title-panel"><div class="game-title-emblem">'+(icons[gameId]||"✦")+'</div><div class="game-title-copy"><div class="game-title-kicker">KAZO / '+esc(meta.toUpperCase())+'</div><h2>'+esc(t)+'</h2><p>'+(subtitles[gameId]||"Твой ход. Твоя стратегия. Твоя победа.")+'</p></div><div id="notice" class="status hidden"></div></section>'}
